def flatten(data):
    flat = {}

    def walk(value, path):
        if isinstance(value, dict) and value:
            for key, child in value.items():
                walk(child, f"{path}.{key}")
        elif isinstance(value, list) and value:
            for position, child in enumerate(value):
                walk(child, f"{path}.{position}")
        else:
            flat[path] = value              # a leaf, or an empty dict/list kept as it is

    for key, value in data.items():
        walk(value, key)
    return flat


def unflatten(flat):
    tree = {}
    for path, value in flat.items():
        *parents, last = path.split(".")
        node = tree
        for key in parents:
            node = node.setdefault(key, {})
        node[last] = value
    return _lists_from_positions(tree)


def _lists_from_positions(node):
    """Turn every dict whose keys are all digits into a list, in numeric order. An empty dict is a real value and stays."""
    if not isinstance(node, dict):
        return node
    node = {key: _lists_from_positions(child) for key, child in node.items()}
    if node and all(key.isdigit() for key in node):
        return [node[key] for key in sorted(node, key=int)]
    return node
